window.__PHD.push(" 2026\", \"url\": \"https://doi.org/10.1109/vrw70859.2026.00296\", \"link_to_user\": \"\u591a\u611f\u5b98\u6c89\u6d78\u9057\u4ea7\u4f53\u9a8c\uff08\u5386\u53f2\u98de\u673a\uff09\u2192 \u591a\u611f\u5b98\u9057\u4ea7 XR\", \"title_zh\": \"\u591a\u611f\u5b98\u864e\u86fe\u5f0f\u98de\u673a VR \u98de\u884c\u4f53\u9a8c\uff1a\u8fdb\u884c\u4e2d\u7814\u7a76\"}], \"evidence_projects_funding\": \"Warwick \u4e3b\u9875\u9886\u57df\uff1aGraphics, AR and games\uff1bHuman-centred computing\u3002GtR\uff1aEPSRC 'Dynamic Real-World Lighting for Complex Scenes with Applications to Design of the Built Environment'\uff08PI\uff09\u3001AHRC SCHEDAR \u821e\u8e48\u6587\u5316\u9057\u4ea7 AR \u9879\u76ee\u56e2\u961f\uff1bRoyal Society Industrial Fellow\uff1bWMG \u7814\u7a76\u751f\u5b66\u4f4d\u4e3b\u4efb\u3002\", \"fit_to_user\": \"\u5149\u7167/HDR \u611f\u77e5 + \u9057\u4ea7\u865a\u62df\u4f53\u9a8c + \u7528\u6237 OSRAM/LEDVANCE \u7167\u660e\u4ea7\u54c1\u80cc\u666f\uff0c\u4e09\u8005\u9ad8\u5ea6\u5951\u5408\uff1b\u4f5c\u4e3a\u7814\u7a76\u751f\u5b66\u4f4d\u4e3b\u4efb\u719f\u6089\u62db\u751f\u6d41\u7a0b\u3002\", \"counterargument_risk\": \"\u8fd1\u5e74\u4ea7\u51fa\u504f\u8ba1\u7b97\u673a\u89c6\u89c9/\u6df1\u5ea6\u5b66\u4e60\uff08HDR\u3001\u4f4e\u5149\u589e\u5f3a\u3001\u81ea\u52a8\u9a7e\u9a76\uff09\uff0c\u9057\u4ea7\u4e0e\u4ea4\u4e92\u662f\u6b21\u8981\u65b9\u5411\uff1b\u4e0e\u5df2\u6709\u5bfc\u5e08 Alan Chalmers \u540c\u7ec4\uff0c\u53ef\u80fd\u88ab\u89c6\u4e3a\u540c\u4e00\u56e2\u961f\uff1bWMG \u504f\u5de5\u7a0b\uff0c\u9700\u6280\u672f\u80fd\u529b\u3002\", \"email_hook\": \"Your state-of-the-art review 'Illuminating the past' and your work on perception-based rendering are the closest research I know to my interest in narrative lighting for heritage.\", \"sources\": [\"https://profiles.warwick.ac.uk/essgfz-kurt-debattista\", \"https://warwick.ac.uk/fac/sci/wmg/dev-test-area/research-areas-people-pages/visualisation/\", \"https://gtr.ukri.org/person/3CBAA51E-0A95-4F42-AA93-6912090E53C6\", \"https://orcid.org/0000-0003-2982-5199\"], \"verified\": true, \"csc_note\": \"\u534e\u5a01 CSC \u7ebf active\uff08CSC\u2013Warwick \u8054\u5408\u5956\u5b66\u91d1\uff0c\u9700\u6838\u5bf9 2027 \u622a\u6b62\u4e0e\u5b66\u79d1\u8303\u56f4\uff09\u3002\", \"matched_keywords\": [\"narrative lighting\", \"virtual heritage\", \"VR\", \"applied perception\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"K.Debattista@warwick.ac.uk\", \"subject\": \"PhD enquiry (2027): narrative lighting and perception in heritage XR\", \"body\": \"Dear Professor Debattista,\\n\\nYour state-of-the-art review 'Illuminating the past' and your work on perception-based rendering for VR are the closest research I know to my interest in narrative lighting for heritage. I would like to apply for a PhD at WMG.\\n\\nSince November 2025 I have directed the Digital Intangible Cultural Heritage Design and Production teaching and research office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting and leading a VR collaborative lighting design project (JAT251371). Before that I was a lighting hardware product manager: at OSRAM/LEDVANCE I ran nine product families (~100 SKUs, US$8M in sales) and worked on light-distribution analysis for Abu Dhabi's Zayed airport; at LEEDARSON I led user research for smart-lighting lines that sold over US$30M. Physical light is therefore familiar ground, and my office can support perceptual studies with participants.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as Three.js GPU particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction combined with responsive, narrative lighting, both virtual and physical, guides attention, conveys process and shapes emotional engagement with heritage objects, using perceptual experiments alongside co-design and a museum deployment.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI hope to apply for 2027 entry, possibly through the CSC\u2013Warwick scholarship. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a'Illuminating the past' \u865a\u62df\u8003\u53e4\u7167\u660e\u7efc\u8ff0 + \u611f\u77e5\u6e32\u67d3 \u2194 \u53d9\u4e8b\u7167\u660e\uff1b\u70b9\u51fa\u7528\u6237\u7167\u660e\u884c\u4e1a\u7ecf\u5386\uff08OSRAM/LEDVANCE\u3001LEEDARSON\uff09\u3002\u4ed6\u4e0e\u5df2\u5217 Alan Chalmers \u540c\u7ec4\uff0c\u53ef\u540c\u65f6\u63d0\u4e8c\u4eba\u8054\u5408\u6307\u5bfc\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1aCSC\u2013Warwick \u5b66\u79d1\u8303\u56f4/\u622a\u6b62\uff1bWMG \u5bf9\u8bbe\u8ba1\u80cc\u666f\u7684\u5165\u5b66\u8981\u6c42\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff082027\uff09\uff1a\u9057\u4ea7 XR \u4e2d\u7684\u53d9\u4e8b\u7167\u660e\u4e0e\u611f\u77e5\", \"body_zh\": \"\u5c0a\u656c\u7684 Debattista \u6559\u6388\uff1a\\n\\n\u60a8\u7684\u524d\u6cbf\u7efc\u8ff0\\\"Illuminating the past\\\"\uff08\u300a\u7167\u4eae\u8fc7\u53bb\u300b\uff09\u4ee5\u53ca\u60a8\u5173\u4e8e VR \u4e2d\u57fa\u4e8e\u611f\u77e5\u7684\u6e32\u67d3\u7684\u7814\u7a76\uff0c\u662f\u6211\u6240\u77e5\u9053\u7684\u4e0e\u6211\u5bf9\u9057\u4ea7\u53d9\u4e8b\u7167\u660e\u7684\u5174\u8da3\u6700\u63a5\u8fd1\u7684\u7814\u7a76\u3002\u6211\u5e0c\u671b\u7533\u8bf7\u534e\u5a01\u5236\u9020\u96c6\u56e2\uff08WMG\uff09\u7684\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u9500\u552e\u989d 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed\uff08\u624e\u8036\u5fb7\uff09\u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u9500\u552e\u989d\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u56e0\u6b64\uff0c\u5b9e\u4f53\u5149\u5bf9\u6211\u6765\u8bf4\u662f\u719f\u6089\u7684\u9886\u57df\uff0c\u6211\u7684\u6559\u7814\u5ba4\u4e5f\u80fd\u652f\u6301\u6709\u53c2\u4e0e\u8005\u7684\u611f\u77e5\u7814\u7a76\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u77f3\u50cf\u663e\u73b0\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u91cd\u5efa\u4e3a Three.js GPU \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u57c3\u201d\u5e76\u53cc\u624b\u5408\u5341\uff0c\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u50cf\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u5bf9\u4e2d\u56fd\u9752\u94dc\u5668\u505a\u4e86\u540c\u6837\u7684\u5904\u7406\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u624b\u52bf\u9a71\u52a8\u7684\u4ea4\u4e92\u7ed3\u5408\u865a\u62df\u4e0e\u5b9e\u4f53\u7684\u54cd\u5e94\u5f0f\u53d9\u4e8b\u7167\u660e\uff0c\u5982\u4f55\u5f15\u5bfc\u6ce8\u610f\u529b\u3001\u4f20\u8fbe\u8fc7\u7a0b\u5e76\u5851\u9020\u4e0e\u9057\u4ea7\u5bf9\u8c61\u7684\u60c5\u611f\u8054\u7ed3\uff0c\u7814\u7a76\u5c06\u91c7\u7528\u611f\u77e5\u5b9e\u9a8c\uff0c\u5e76\u7ed3\u5408\u534f\u540c\u8bbe\u8ba1\u548c\u535a\u7269\u9986\u90e8\u7f72\u3002\\n\\n\u5766\u7387\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u5408\u8457\u8fc7\u4e24\u7bc7 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5173\u4e8e MR \u5b9a\u5236\u65b9\u6cd5\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u6211\u5e0c\u671b\u4e8e 2027 \u5e74\u5165\u5b66\uff0c\u53ef\u80fd\u901a\u8fc7 CSC\u2013\u534e\u5a01\u5956\u5b66\u91d1\uff08CSC\u2013Warwick scholarship\uff09\u7533\u8bf7\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\\nHanlei (Eli) Zeng\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Khairul Fadhli Mohammad\", \"status\": \"alumni\", \"thesis_title\": \"The Effects of Multi-Sensory Features on Learning Outcomes and Player Experience in Cultural Heritage Serious Game\", \"topic_zh\": \"\u591a\u611f\u5b98\u7279\u5f81\u5bf9\u6587\u5316\u9057\u4ea7\u4e25\u8083\u6e38\u620f\u5b66\u4e60\u6548\u679c\u4e0e\u73a9\u5bb6\u4f53\u9a8c\u7684\u5f71\u54cd\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/198967/1/WRAP_Theses_Mohammad_2024_Redacted.pdf\", \"graduation_year\": 2024}, {\"name\": \"William Naylor\", \"status\": \"alumni\", \"thesis_title\": \"Perception-based adaptive tick rates: efficient networks for immersive and stable collaborative virtual reality\", \"topic_zh\": \"\u57fa\u4e8e\u611f\u77e5\u7684\u81ea\u9002\u5e94\u7f51\u7edc\u5237\u65b0\u7387\uff0c\u7528\u4e8e\u534f\u4f5c VR\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/191491/\", \"graduation_year\": 2024}, {\"name\": \"Mark Patrick Kirya\", \"status\": \"alumni\", \"thesis_title\": \"Using virtual experiences to facilitate refugees' integration in third countries\", \"topic_zh\": \"\u7528\u865a\u62df\u4f53\u9a8c\uff08360\u00b0\u89c6\u9891/VR\uff09\u5e2e\u52a9\u96be\u6c11\u878d\u5165\u7b2c\u4e09\u56fd\", \"url\": \"https://wrap.warwick.ac.uk/view/author_id/347048.html\", \"graduation_year\": 2021}, {\"name\": \"Demetris Marnerides\", \"status\": \"alumni\", \"thesis_title\": \"Deep learning for high dynamic range imaging\", \"topic_zh\": \"\u6df1\u5ea6\u5b66\u4e60 HDR \u6210\u50cf\", \"url\": \"https://wrap.warwick.ac.uk/view/author_id/341524.html\", \"graduation_year\": 2019}, {\"name\": \"Timothy E. Bradley\", \"status\": \"alumni\", \"thesis_title\": \"Visual attention for high-fidelity imaging\", \"topic_zh\": \"\u9ad8\u4fdd\u771f\u6210\u50cf\u4e2d\u7684\u89c6\u89c9\u6ce8\u610f\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/106379\", \"graduation_year\": 2017}, {\"name\": \"Ratnajit Mukherjee\", \"status\": \"alumni\", \"thesis_title\": \"Accurate light and colour reproduction in high dynamic range video compression\", \"topic_zh\": \"HDR \u89c6\u9891\u538b\u7f29\u4e2d\u7684\u5149\u4e0e\u8272\u5f69\u51c6\u786e\u518d\u73b0\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/90712/\", \"graduation_year\": 2017}, {\"name\": \"Amar Pravin Dhokia\", \"status\": \"alumni\", \"thesis_title\": \"High Fidelity Olfaction Simulation for Virtual Environments\", \"topic_zh\": \"\u865a\u62df\u73af\u5883\u4e2d\u7684\u9ad8\u4fdd\u771f\u55c5\u89c9\u6a21\u62df\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/115875/1/WRAP_Theses_Dhokia_2017.pdf\", \"graduation_year\": 2017}, {\"name\": \"Jonathan Hatchett\", \"status\": \"alumni\", \"thesis_title\": \"Efficient and Adaptable High Dynamic Range Compression\", \"topic_zh\": \"\u9ad8\u6548\u81ea\u9002\u5e94 HDR \u538b\u7f29\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/106777/1/WRAP_Theses_Hatchett_2017.pdf\", \"graduation_year\": 2017}, {\"name\": \"\uff08\u59d3 \u2026Namee\uff0cWRAP \u6587\u4ef6\u540d\u622a\u65ad\uff09\", \"status\": \"alumni\", \"thesis_title\": \"Efficient streaming for high fidelity imaging\", \"topic_zh\": \"\u9ad8\u4fdd\u771f\u6210\u50cf\u7684\u9ad8\u6548\u6d41\u4f20\u8f93\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/109950/\", \"graduation_year\": 2017}, {\"name\": \"Pinar Satilmis\", \"status\": \"alumni\", \"thesis_title\": \"High fidelity sky models\", \"topic_zh\": \"\u9ad8\u4fdd\u771f\u5929\u7a7a\u5149\u7167\u6a21\u578b\uff08\u571f\u8033\u5176\u653f\u5e9c\u8d44\u52a9\uff09\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/89934/\", \"graduation_year\": 2016}, {\"name\": \"Efstratios Doukakis\", \"status\": \"alumni\", \"thesis_title\": \"Resource allocation for multi-sensory virtual environments\", \"topic_zh\": \"\u591a\u611f\u5b98\u865a\u62df\u73af\u5883\u4e2d\u7684\u8d44\u6e90\u5206\u914d\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/92730/\", \"graduation_year\": 2016}, {\"name\": \"Danel Zholzhanova\", \"status\": \"current\", \"research_topic\": \"Virtual chocolate: olfactory cues in multisensory VR on perceived realism, food enjoyment, and snack choices (2025 \u8bba\u6587\uff0c\u8eab\u4efd\u63a8\u65ad\u4e3a\u535a\u58eb\u751f)\", \"topic_zh\": \"\u591a\u611f\u5b98 VR \u4e2d\u55c5\u89c9\u7ebf\u7d22\u5bf9\u771f\u5b9e\u611f\u4e0e\u996e\u98df\u884c\u4e3a\u7684\u5f71\u54cd\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/191916\"}, {\"name\": \"Changrui Chen\", \"status\": \"current\", \"research_topic\": \"Semi-supervised object detection / pseudo-labelling (ECCV 2022, 2024)\", \"topic_zh\": \"\u534a\u76d1\u7763\u76ee\u6807\u68c0\u6d4b\uff08\u4e0e Jungong Han \u5408\u4f5c\uff09\", \"url\": \"https://wrap.warwick.ac.uk/id/eprint/188781/\", \"background\": \"\u8bba\u6587\u8d44\u52a9\u65b9\u6807\u6ce8 China Scholarship Council\", \"chinese_or_csc\": true}, {\"name\": \"Jingkun Chen\", \"status\": \"alumni\", \"thesis_title\": \"Semi-supervised medical image segmentation (TMI 2023, TIP 2025)\", \"topic_zh\": \"\u534a\u76d1\u7763\u533b\u5b66\u56fe\u50cf\u5206\u5272\uff08\u4e0e Jungong Han\u3001Jianguo Zhang \u5408\u4f5c\uff0c\u8eab\u4efd\u63a8\u65ad\u4e3a\u535a\u58eb\u751f\uff09\", \"url\": \"https://wrap.warwick.ac.uk/view/author_id/374571.default.html\"}, {\"name\": \"Lvyin Duan\", \"status\": \"current\", \"research_topic\": \"Deep controllable backlight dimming for HDR displays (2022)\", \"topic_zh\": \"HDR \u663e\u793a\u5668\u6df1\u5ea6\u53ef\u63a7\u80cc\u5149\u8c03\u5149\uff08\u8eab\u4efd\u63a8\u65ad\uff09\", \"url\": \"https://wrap.warwick.ac.uk/view/author_id/341524.html\"}, {\"name\": \"Edward Ren Kai Neo\", \"status\": \"alumni\", \"thesis_title\": \"Deep learning-enabled chemometric analysis of spectral data for plastic waste sorting: innovation report\", \"topic_zh\": \"\u6df1\u5ea6\u5b66\u4e60\u5316\u5b66\u8ba1\u91cf\u5206\u6790\u7528\u4e8e\u5851\u6599\u5206\u62e3\uff08EngD/\u521b\u65b0\u62a5\u544a\uff09\", \"url\": \"https://wrap.warwick.ac.uk/view/author_id/382678.type.html\", \"graduation_year\": 2024}], \"total_estimate\": \"\u5df2\u6bd5\u4e1a\uff08\u8fd1 10 \u5e74\uff09\u226515\uff08WRAP \u4e2d Chalmers+Debattista \u5171\u540c\u6307\u5bfc\u5373\u5341\u4f59\u7bc7\uff09/ \u5728\u8bfb\u7ea6 5\u201310\", \"student_pattern_zh\": \"\u9ad8\u4fdd\u771f\u6210\u50cf\uff08HDR \u89c6\u9891/\u538b\u7f29/\u663e\u793a\uff09\u3001\u591a\u611f\u5b98 VR\uff08\u55c5\u89c9\u3001\u89c6\u542c\u8d44\u6e90\u5206\u914d\uff09\u3001\u611f\u77e5\u4e0e\u5fc3\u7406\u7269\u7406\u5b9e\u9a8c\u3001\u8fd1\u5e74\u6269\u5c55\u5230\u6df1\u5ea6\u5b66\u4e60 CV \u4e0e VR \u793e\u4f1a\u5e94\u7528\uff08\u96be\u6c11\u878d\u5165\u3001\u6587\u5316\u9057\u4ea7\u4e25\u8083\u6e38\u620f\uff09\uff1b\u4ee5\u5b9e\u9a8c\u578b\uff08\u5fc3\u7406\u7269\u7406+\u7edf\u8ba1\uff09\u4e3a\u4e3b\uff0cDebattista \u8d1f\u8d23\u7edf\u8ba1\u65b9\u6cd5\u3002\", \"design_background_ok_zh\": \"\u535a\u58eb\u591a\u4e3a CS/\u5de5\u7a0b\u80cc\u666f\uff1bMark Kirya\uff08\u96be\u6c11 VR\uff09\u4e0e Khairul Fadhli Mohammad\uff08\u6587\u5316\u9057\u4ea7\u4e25\u8083\u6e38\u620f\uff09\u663e\u793a\u5e94\u7528/\u793e\u79d1\u53d6\u5411\u8bfe\u9898\u53ef\u88ab\u63a5\u6536\uff0c\u4f46\u672a\u89c1\u660e\u786e\u827a\u672f\u8bbe\u8ba1\u5b66\u4f4d\u8bc1\u636e\u3002\", \"chinese_students_zh\": \"WRAP \u8bb0\u5f55\u663e\u793a Debattista \u4e0e Jungong Han \u5408\u4f5c\u6307\u5bfc\u7684 Changrui Chen \u8bba\u6587\u6807\u6ce8 CSC \u8d44\u52a9\uff1b\u53e6\u6709 Jingkun Chen\u3001Lvyin Duan \u7b49\u534e\u4eba\u5408\u4f5c\u8005\u2014\u2014CSC \u8def\u5f84\u6709\u5148\u4f8b\u3002\", \"implication_zh\": \"\u6700\u4f73\u5207\u5165\uff1aKhairul Fadhli Mohammad 2024 \u5e74\u300a\u591a\u611f\u5b98\u7279\u5f81\u5bf9\u6587\u5316\u9057\u4ea7\u4e25\u8083\u6e38\u620f\u5b66\u4e60\u6548\u679c\u7684\u5f71\u54cd\u300b\u2014\u2014\u4e0e\u7528\u6237\u201c\u6570\u5b57\u9057\u4ea7+\u5177\u8eab/\u7167\u660e\u53d9\u4e8b\u201d\u9ad8\u5ea6\u5951\u5408\uff0c\u53ef\u63d0\u51fa\u628a\u201c\u53d9\u4e8b\u7167\u660e/\u624b\u52bf\u201d\u4f5c\u4e3a\u65b0\u7684\u611f\u5b98\u901a\u9053\u505a\u5b9e\u9a8c\u3002\u98ce\u9669\uff1a\u7ec4\u5185\u5f3a\u8c03\u5fc3\u7406\u7269\u7406\u5b9e\u9a8c\u4e0e\u7edf\u8ba1\uff0c\u9700\u5728\u7814\u7a76\u8ba1\u5212\u4e2d\u5199\u6e05\u5bf9\u7167\u5b9e\u9a8c\u8bbe\u8ba1\uff1bWMG \u535a\u58eb\u8d39\u7528\u8f83\u9ad8\uff0cCSC \u53ef\u8986\u76d6\u3002\", \"sources\": [\"https://wrap.warwick.ac.uk/id/eprint/198967/1/WRAP_Theses_Mohammad_2024_Redacted.pdf\", \"https://wrap.warwick.ac.uk/id/eprint/191491/\", \"https://wrap.warwick.ac.uk/id/eprint/188781/\", \"https://wrap.warwick.ac.uk/view/theses/Warwick_Manufacturing_Group.html\"], \"searched\": [\"WRAP\uff08Supervisor \u5b57\u6bb5\u3001\u4f5c\u8005\u6d4f\u89c8\u9875\u3001\u8bba\u6587\u81f4\u8c22\uff09\", \"WMG Visualisation \u7ec4\u9875\u9762\", \"web_search\uff08CSC \u8d44\u52a9\u6807\u6ce8\uff09\"]}, \"title_zh\": \"\u6559\u6388\uff1bWMG \u7814\u7a76\u5b66\u4f4d\u4e3b\u4efb\", \"unit_zh\": \"\u534e\u5a01\u5927\u5b66 WMG \u53ef\u89c6\u5316\u7814\u7a76\u7ec4\", \"evidence_projects_funding_zh\": \"Warwick \u4e3b\u9875\u9886\u57df\uff1a\u56fe\u5f62\u3001AR \u4e0e\u6e38\u620f\uff08Graphics, AR and games\uff09\uff1b\u4ee5\u4eba\u4e3a\u672c\u7684\u8ba1\u7b97\uff08Human-centred computing\uff09\u3002GtR\uff1aEPSRC\u201c\u590d\u6742\u573a\u666f\u7684\u52a8\u6001\u771f\u5b9e\u4e16\u754c\u7167\u660e\u53ca\u5176\u5728\u5efa\u6210\u73af\u5883\u8bbe\u8ba1\u4e2d\u7684\u5e94\u7528\u201d\uff08Dynamic Real-World Lighting for Complex Scenes with Applications to Design of the Built Environment\uff0cPI\uff09\u3001AHRC SCHEDAR \u821e\u8e48\u6587\u5316\u9057\u4ea7 AR \u9879\u76ee\u56e2\u961f\uff1b\u82f1\u56fd\u7687\u5bb6\u5b66\u4f1a\u4ea7\u4e1a\u7814\u7a76\u5458\uff08Royal Society Industrial Fellow\uff09\uff1bWMG \u7814\u7a76\u751f\u5b66\u4f4d\u4e3b\u4efb\u3002\", \"email_hook_zh\": \"\u60a8\u7684\u524d\u6cbf\u7efc\u8ff0\u300a\u7167\u4eae\u8fc7\u53bb\u300b\uff08Illuminating the past\uff09\u4ee5\u53ca\u57fa\u4e8e\u611f\u77e5\u7684\u6e32\u67d3\u7814\u7a76\uff0c\u662f\u6211\u6240\u77e5\u4e0e\u6211\u5bf9\u9057\u4ea7\u53d9\u4e8b\u7167\u660e\u7684\u5174\u8da3\u6700\u63a5\u8fd1\u7684\u7814\u7a76\u3002\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Leighton Evans\", \"school_en\": \"Swansea University\", \"school_zh\": \"\u65af\u65fa\u897f\u5927\u5b66\", \"country\": \"\", \"title\": \"Professor of Media Theory; co-lead Media and Communication\", \"unit\": \"School of Culture and Communication (Media)\", \"homepage\": \"https://www.swansea.ac.uk/staff/l.evans\", \"email\": \"l.evans@swansea.ac.uk\", \"relevance\": 8, \"claim\": \"Evans \u662f\u65af\u65fa\u897f\u5a92\u4f53\u7406\u8bba\u6559\u6388\u3001VR/\u5143\u5b87\u5b99\u73b0\u8c61\u5b66\u7814\u7a76\u8005\uff082026 \u5a01\u5c14\u58eb\u5b66\u4f1a\u9662\u58eb\uff09\uff0c\u6b63\u5728\u6307\u5bfc'\u535a\u7269\u9986\u89c2\u4f17\u8eab\u4efd\u9700\u6c42 \u00d7 VR \u4e2a\u6027\u5316\u4f53\u9a8c'\u7684\u535a\u58eb\uff0c\u5e76\u4e0e\u5b66\u751f\u53d1\u8868\u4e86 XR \u4e0e\u535a\u7269\u9986\u5b9e\u8df5\u8bba\u6587\uff0c\u662f\u65af\u65fa\u897f\u4e0e\u7528\u6237\u6700\u5bf9\u53e3\u7684\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.swansea.ac.uk/staff/l.evans\", \"evidence_papers\": [{\"title\": \"The museum of digital things: extended reality and museum practices (with E. Song)\", \"year\": 2024, \"venue\": \"Frontiers in Virtual Reality 5\", \"url\": \"https://doi.org/10.3389/frvir.2024.1396280\", \"link_to_user\": \"XR \u4e0e\u535a\u7269\u9986\u5b9e\u8df5 \u2192 \u7528\u6237\u535a\u7269\u9986\u624b\u52bf XR \u7684\u76f4\u63a5\u5bf9\u8bdd\u5bf9\u8c61\", \"title_zh\": \"\u6570\u5b57\u7269\u7684\u535a\u7269\u9986\uff1a\u6269\u5c55\u73b0\u5b9e\u4e0e\u535a\u7269\u9986\u5b9e\u8df5\uff08\u4e0e E. Song \u5408\u4f5c\uff09\"}, {\"title\": \"Hermeneutic Relations in VR: Immersion, Embodiment, Presence and HCI in VR Gaming (with M. Rzeszewski)\", \"year\": 2020, \"venue\": \"HCI in Games, HCII 2020 (Springer)\", \"url\": \"https://www.swansea.ac.uk/staff/l.evans\", \"link_to_user\": \"\u6c89\u6d78/\u5177\u8eab/\u4e34\u573a\u4e0e HCI \u2192 \u624b\u52bf\u5177\u8eab\u4ea4\u4e92\u7684\u73b0\u8c61\u5b66\u6846\u67b6\", \"title_zh\": \"VR \u4e2d\u7684\u8be0\u91ca\u5b66\u5173\u7cfb\uff1aVR \u6e38\u620f\u4e2d\u7684\u6c89\u6d78\u3001\u5177\u8eab\u3001\u4e34\u573a\u611f\u4e0e\u4eba\u673a\u4ea4\u4e92\uff08\u4e0e M. Rzeszewski \u5408\u8457\uff09\"}, {\"title\": \"A sense of place in virtual reality: focus, embodiment, and hermeneutics as a model of placehood in virtual worlds\", \"year\": 2026, \"venue\": \"Handbook on Sense of Place (Edward Elgar), pp.145-158\", \"url\": \"https://doi.org/10.4337/9781035337217.00020\", \"link_to_user\": \"VR \u573a\u6240\u611f \u2192 \u53d9\u4e8b\u7167\u660e\u8425\u9020\u7684\u7a7a\u95f4\u6c1b\u56f4\", \"title_zh\": \"\u865a\u62df\u73b0\u5b9e\u4e2d\u7684\u5730\u65b9\u611f\uff1a\u4ee5\u4e13\u6ce8\u3001\u5177\u8eab\u4e0e\u8be0\u91ca\u5b66\u4f5c\u4e3a\u865a\u62df\u4e16\u754c\u5730\u65b9\u6027\u7684\u6a21\u578b\"}], \"evidence_projects_funding\": \"\u4e3b\u9875\uff1aAvailable For Postgraduate Supervision\uff1b\u8457\u4f5c The Re-emergence of Virtual Reality (2018)\u3001From Microverse to Metaverse (2022)\u3001Virtual Reality Gaming (ed., 2025)\uff1b2023 Dillwyn Medal\uff1b2026 FLSW\uff1b\u66fe\u4efb CODAH \u6570\u5b57\u827a\u672f\u4e0e\u4eba\u6587\u4e2d\u5fc3\u4e3b\u4efb\uff1b\u6307\u5bfc Zhennuo Song\uff08VR \u535a\u7269\u9986\u4e2a\u6027\u5316\u4f53\u9a8c\uff09\u3001Evelyn Song\uff08VR/AR \u4e0e\u6587\u5316\u9057\u4ea7\uff09\u3002\", \"fit_to_user\": \"\u5df2\u5728\u5e26\u4e2d\u56fd\u5b66\u751f\u505a VR \u535a\u7269\u9986\u65b9\u5411\uff0c\u9898\u76ee\u4e0e\u7528\u6237\u9ad8\u5ea6\u91cd\u5408\uff1b\u5177\u8eab/\u4e34\u573a\u73b0\u8c61\u5b66\u53ef\u4e3a\u624b\u52bf+\u53d9\u4e8b\u7167\u660e\u63d0\u4f9b\u7406\u8bba\uff1b\u5a92\u4f53\u5b66\u9662\u63a5\u53d7\u8bbe\u8ba1/\u5b9e\u8df5\u80cc\u666f\u3002\", \"counterargument_risk\": \"\u7406\u8bba/\u8d28\u6027\u53d6\u5411\uff0c\u4e0d\u505a\u7cfb\u7edf\u5f00\u53d1\u6216\u5bf9\u7167\u5b9e\u9a8c\uff1b\u65af\u65fa\u897f CSC \u4e3b\u8981\u89c1\u4e8e\u7406\u5de5\u5b66\u9662\u62db\u52df\uff08S&E\uff09\uff0c\u6587\u5316\u4e0e\u4f20\u64ad\u5b66\u9662\u662f\u5426\u6709\u540d\u989d\u5f85\u786e\u8ba4\u3002\", \"email_hook\": \"Your article with Evelyn Song, 'The museum of digital things', and your phenomenology of embodiment and presence in VR are the closest scholarly framing I have found for my gesture-driven museum prototypes.\", \"sources\": [\"https://www.swansea.ac.uk/staff/l.evans\", \"https://www.swansea.ac.uk/culture-communication/postgraduate-research-profiles/zhennou-song\", \"https://orcid.org/0000-0002-6875-6301\", \"https://www.learnedsociety.wales/fellow/leighton-evans/\"], \"verified\": true, \"csc_note\": \"\u65af\u65fa\u897f\uff1aCSC \u8054\u5408\u62db\u52df\u4ec5\u89c1\u4e8e\u7406\u5de5\u5b66\u9662\u5404\u7cfb\uff08\u7b2c\u4e09\u65b9\u4fe1\u606f\u6bcf\u7cfb\u6700\u591a 5 \u540d\uff09\uff1b2027 \u622a\u6b62\u672a\u516c\u5e03\uff082026 \u4e3a 2026-02-02\uff09\u3002\", \"matched_keywords\": [\"VR/AR/MR/XR\", \"museum digital cultural heritage\", \"gesture/embodied interaction\", \"digital media\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"l.evans@swansea.ac.uk\", \"subject\": \"PhD enquiry (2027 entry): gesture-driven heritage interaction and narrative lighting\", \"body\": \"Dear Professor Evans,\\n\\nYour article with Evelyn Song, 'The museum of digital things: extended reality and museum practices', and your phenomenological work on embodiment and presence in VR are the closest scholarly framing I have found for my gesture-driven museum prototypes. I would like to apply for a PhD in Media and Communication at Swansea under your supervision, through a Swansea University\u2013CSC scholarship.\\n\\nSince November 2025 I have directed the Digital Intangible Cultural Heritage Design and Production teaching and research office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting and leading a VR collaborative lighting design project (JAT251371). Before that I was a lighting hardware product manager: at OSRAM/LEDVANCE I ran nine product families (~100 SKUs, US$8M in sales) and worked on light-distribution analysis for Abu Dhabi's Zayed airport; at LEEDARSON I led user research for smart-lighting lines that sold over US$30M. My office provides heritage content and participants for prototype studies.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as Three.js GPU particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction and narrative lighting in museum XR shape embodiment, presence and visitors' sense of place, combining a phenomenological framework with prototype-based studies. Your work on VR, embodiment and museums would give this project its theoretical core, and my prototypes would add a practice-based dimension.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nWould you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1aSong & Evans 2024\u300aThe museum of digital things\u300b\uff1b\u4ed6\u5df2\u5728\u5e26\u4e2d\u56fd\u5b66\u751f\u505a VR \u535a\u7269\u9986\u3002\u65af\u65fa\u897f\u9996\u9009\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1a\u6587\u5316\u4e0e\u4f20\u64ad\u5b66\u9662\u662f\u5426\u6709 CSC \u652f\u6301\u540d\u989d\uff08\u5b98\u65b9\u53ea\u89c1\u7406\u5de5\u5b66\u9662 CSC \u62db\u52df\uff09\uff1b2027 \u622a\u6b62\u672a\u516c\u5e03\uff082026 \u4e3a 2/2\uff09\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff082027 \u5e74\u5165\u5b66\uff09\uff1a\u624b\u52bf\u9a71\u52a8\u7684\u9057\u4ea7\u4ea4\u4e92\u4e0e\u53d9\u4e8b\u7167\u660e\", \"body_zh\": \"\u5c0a\u656c\u7684 Evans \u6559\u6388\uff1a\\n\\n\u60a8\u4e0e Evelyn Song \u5408\u8457\u7684\u6587\u7ae0'The museum of digital things: extended reality and museum practices'\uff08\u300a\u6570\u5b57\u7269\u7684\u535a\u7269\u9986\uff1a\u6269\u5c55\u73b0\u5b9e\u4e0e\u535a\u7269\u9986\u5b9e\u8df5\u300b\uff09\uff0c\u4ee5\u53ca\u60a8\u5173\u4e8e VR \u4e2d\u5177\u8eab\u4e0e\u5728\u573a\u7684\u73b0\u8c61\u5b66\u7814\u7a76\uff0c\u662f\u6211\u4e3a\u81ea\u5df1\u7684\u624b\u52bf\u9a71\u52a8\u535a\u7269\u9986\u539f\u578b\u6240\u627e\u5230\u7684\u6700\u63a5\u8fd1\u7684\u5b66\u672f\u6846\u67b6\u3002\u6211\u5e0c\u671b\u901a\u8fc7\u65af\u65fa\u897f\u5927\u5b66\u2013CSC \u5956\u5b66\u91d1\uff0c\u5728\u60a8\u7684\u6307\u5bfc\u4e0b\u7533\u8bf7\u65af\u65fa\u897f\u5927\u5b66\u5a92\u4f53\u4e0e\u4f20\u64ad\u4e13\u4e1a\u7684\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u9500\u552e\u989d 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed\uff08\u624e\u8036\u5fb7\uff09\u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u9500\u552e\u989d\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u6211\u7684\u6559\u7814\u5ba4\u80fd\u4e3a\u539f\u578b\u7814\u7a76\u63d0\u4f9b\u9057\u4ea7\u5185\u5bb9\u548c\u53c2\u4e0e\u8005\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u77f3\u50cf\u663e\u73b0\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u91cd\u5efa\u4e3a Three.js GPU \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u57c3\u201d\u5e76\u53cc\u624b\u5408\u5341\uff0c\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u50cf\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u5bf9\u4e2d\u56fd\u9752\u94dc\u5668\u505a\u4e86\u540c\u6837\u7684\u5904\u7406\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u535a\u7269\u9986 XR \u4e2d\u624b\u52bf\u9a71\u52a8\u7684\u4ea4\u4e92\u4e0e\u53d9\u4e8b\u7167\u660e\u5982\u4f55\u5851\u9020\u5177\u8eab\u6027\u3001\u5728\u573a\u611f\u548c\u89c2\u4f17\u7684\u5730\u65b9\u611f\uff0c\u628a\u73b0\u8c61\u5b66\u6846\u67b6\u4e0e\u57fa\u4e8e\u539f\u578b\u7684\u7814\u7a76\u76f8\u7ed3\u5408\u3002\u60a8\u5173\u4e8e VR\u3001\u5177\u8eab\u4e0e\u535a\u7269\u9986\u7684\u7814\u7a76\u5c06\u6784\u6210\u8fd9\u4e2a\u9879\u76ee\u7684\u7406\u8bba\u6838\u5fc3\uff0c\u800c\u6211\u7684\u539f\u578b\u5c06\u589e\u52a0\u5b9e\u8df5\u578b\u7684\u7ef4\u5ea6\u3002\\n\\n\u5766\u7387\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u5408\u8457\u8fc7\u4e24\u7bc7 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5173\u4e8e MR \u5b9a\u5236\u65b9\u6cd5\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\\nHanlei (Eli) Zeng\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"total_estimate\": \"Cronfa/\u5458\u5de5\u9875\u53ef\u67e5\uff1a\u535a\u58eb\u5df2\u6bd5\u4e1a 3\uff082023\u20132025\uff09\u3001\u5728\u8bfb 2+\uff08\u542b Zhennuo Song \u7b49\uff09\uff0c\u53e6\u6709\u591a\u540d MA/MRes\uff1b\u5b98\u65b9\u9875\u8868\u793a\u6b22\u8fce\u6570\u5b57\u5a92\u4f53/VR/AR/\u5a92\u4ecb\u7406\u8bba\u65b9\u5411\u535a\u58eb\u7533\u8bf7\", \"students\": [{\"name\": \"Zhennuo Song (Evelyn Song)\", \"status\": \"current\", \"research_topic\": \"(Working title) Incorporating the identity-related needs of visitors with Virtual Reality systems for designing personalized interactive museum experiences (supervisors Leighton Evans & Sian Rees)\", \"topic_zh\": \"\u7ed3\u5408\u89c2\u4f17\u8eab\u4efd\u9700\u6c42\u7684 VR \u4e2a\u6027\u5316\u535a\u7269\u9986\u4ea4\u4e92\u4f53\u9a8c\u8bbe\u8ba1\uff1b\u5df2\u4e0e Evans \u5408\u53d1\u300aThe museum of digital things\u300b\u300aImmersion as Convergence\u300b\u300atransmedia museum storytelling and gamification through XR\u300b\", \"url\": \"https://www.swansea.ac.uk/culture-communication/postgraduate-research-profiles/zhennou-song\", \"now\": \"\", \"background\": \"\", \"chinese_or_csc\": null}, {\"name\": \"\uff08Cronfa \u8bb0\u5f55\u4f5c\u8005\u540d\u672a\u5728\u6458\u5f55\u4e2d\u663e\u793a\uff1b\u63a8\u65ad\u53ef\u80fd\u4e3a Zhennuo Song\uff0c\u672a\u8bc1\u5b9e\uff09\", \"status\": \"alumni\", \"graduation_year\": 2024, \"thesis_title\": \"How Do XR Technologies Remediate Museum Curatorial Practices and User Experience?\", \"topic_zh\": \"XR \u5982\u4f55\u91cd\u5851\u535a\u7269\u9986\u7b56\u5c55\u5b9e\u8df5\u4e0e\u89c2\u4f17\u4f53\u9a8c\uff08\u5bfc\u5e08 Evans\u3001Sian Rees\uff09\", \"url\": \"https://cronfa.swan.ac.uk/Record/cronfa67352\", \"now\": \"\", \"background\": \"\", \"chinese_or_csc\": null}, {\"name\": \"\uff08\u59d3\u540d\u672a\u5728\u6458\u5f55\u4e2d\u663e\u793a\uff09\", \"status\": \"alumni\", \"graduation_year\": 2025, \"thesis_title\": \"Exploring the motivations behind crafting identities in virtual reality interactions\", \"topic_zh\": \"VRChat \u7b49\u793e\u4ea4 VR \u4e2d\u7528\u6237\u8bbe\u8ba1\u865a\u62df\u5316\u8eab\u7684\u52a8\u673a\uff08\u4f5c\u8005\u81f4\u8c22\u79f0\u539f\u4e3a Arts and Design \u80cc\u666f\u3001\u8f6c\u5165\u5a92\u4ecb\u7814\u7a76\uff09\", \"url\": \"https://cronfa.swansea.ac.uk/Record/cronfa68918\", \"now\": \"\u6bd5\u4e1a\u524d\u5df2\u4efb\u517c\u804c\u8bb2\u5e08\uff08\u81f4\u8c22\u81ea\u8ff0\uff09\", \"background\": \"\u827a\u672f\u4e0e\u8bbe\u8ba1\u80cc\u666f\uff08\u8bba\u6587\u81f4\u8c22\u660e\u786e\uff09\", \"chinese_or_csc\": null}, {\"name\": \"\uff08\u59d3\u540d\u672a\u5728\u6458\u5f55\u4e2d\u663e\u793a\uff09\", \"status\": \"alumni\", \"graduation_year\": 2023, \"thesis_title\": \"Digital Literacy Education in Welsh Primary and Secondary Schools from the 1960s to the Present\", \"topic_zh\": \"\u5a01\u5c14\u58eb\u4e2d\u5c0f\u5b66\u6570\u5b57\u7d20\u517b\u6559\u80b2\u53f2\uff08William Merrin \u4e0e Evans \u5171\u540c\u6307\u5bfc\uff09\", \"url\": \"https://www.swansea.ac.uk/staff/humanities-and-socialsciences/culture-communication-staff/media-communication-journalism-pr-staff/william.merrin\", \"now\": \"\", \"background\": \"\", \"chinese_or_csc\": null}, {\"name\": \"\uff08\u59d3\u540d\u672a\u5728\u6458\u5f55\u4e2d\u663e\u793a\uff09\", \"status\": \"current\", \"research_topic\": \"Women's Healthcare in Wales: The Role of Social Media and Surveillance Capitalism in Public Attitudes towards the NHS\", \"topic_zh\": \"\u793e\u4ea4\u5a92\u4f53\u4e0e\u76d1\u63a7\u8d44\u672c\u4e3b\u4e49\u5bf9\u516c\u4f17 NHS \u6001\u5ea6\u7684\u5f71\u54cd\uff08\u4e0e Merrin \u5171\u540c\u6307\u5bfc\uff09\", \"url\": \"https://www.swansea.ac.uk/staff/humanities-and-socialsciences/culture-communication-staff/media-communication-journalism-pr-staff/william.merrin\", \"now\": \"\", \"background\": \"\", \"chinese_or_csc\": null}], \"student_pattern_zh\": \"\u5a92\u4ecb\u7406\u8bba/\u73b0\u8c61\u5b66\u53d6\u5411\uff1aVR \u4e34\u573a\u611f\u4e0e\u5316\u8eab\u8eab\u4efd\u3001\u535a\u7269\u9986 XR \u53d9\u4e8b\u4e0e\u7b56\u5c55\u3001\u6570\u5b57\u7d20\u517b\u3001\u6e38\u620f\u4e2d\u7684\u6027\u522b\u4e0e\u9177\u513f\u8868\u5f81\u3002\u4ee5\u8bbf\u8c08\u3001\u73b0\u8c61\u5b66\u5206\u6790\u3001\u6848\u4f8b\u7814\u7a76\u4e3a\u4e3b\uff08\u7406\u8bba+\u8d28\u6027\uff09\uff0c\u504f\u4eba\u6587\u793e\u79d1\u3002\", \"design_background_ok_zh\": \"\u5f3a\u8bc1\u636e\uff1a2025 \u5e74 VR \u5316\u8eab\u8bba\u6587\u4f5c\u8005\u5728\u81f4\u8c22\u4e2d\u660e\u786e\u81ea\u5df1\u6765\u81ea Arts and Design\uff0c\u7ecf Evans \u6307\u5bfc\u8f6c\u578b\u4e3a\u5a92\u4ecb\u7814\u7a76\u535a\u58eb\u3002\", \"chinese_students_zh\": \"Zhennuo Song \u4e3a\u4e2d\u56fd\u59d3\u540d\uff08\u4e0e Evans \u5408\u4f5c\u591a\u7bc7\u535a\u7269\u9986 XR \u8bba\u6587\uff0c\u5408\u4f5c\u8005\u542b Tianran Whyke\u3001Xu Sun \u7b49\u534e\u4eba\u5b66\u8005\uff09\uff1bCSC \u60c5\u51b5\u672a\u6ce8\u660e\u3002\", \"implication_zh\": \"\u4e0e\u7528\u6237\u201c\u535a\u7269\u9986\u6570\u5b57\u6587\u5316\u9057\u4ea7+XR+\u53d9\u4e8b\u201d\u9ad8\u5ea6\u5951\u5408\uff1a\u53ef\u76f4\u63a5\u5f15\u7528 Zhennuo Song \u7684\u201cVR \u4e2a\u6027\u5316\u535a\u7269\u9986\u4f53\u9a8c/\u8de8\u5a92\u4ecb\u535a\u7269\u9986\u53d9\u4e8b\u4e0e\u6e38\u620f\u5316\u201d\uff0c\u5e76\u4ee5\u624b\u52bf\u5177\u8eab\u4ea4\u4e92\u4f5c\u4e3a\u201c\u4e34\u573a\u611f\u4e0e\u5177\u8eab\u201d\u7684\u73b0\u8c61\u5b66\u7814\u7a76\u5bf9\u8c61\u3002Evans \u660e\u786e\u6b22\u8fce VR/AR \u65b9\u5411\u535a\u58eb\uff0c\u4e14\u6709\u8bbe\u8ba1\u80cc\u666f\u5b66\u751f\u6210\u529f\u5148\u4f8b\u3002\u98ce\u9669\uff1a\u5176\u65b9\u6cd5\u504f\u4eba\u6587\u8d28\u6027\uff0c\u82e5\u7528\u6237\u60f3\u505a\u6280\u672f\u539f\u578b\u9700\u53e6\u914d\u8ba1\u7b97\u673a\u7cfb\u5408\u4f5c\u5bfc\u5e08\uff1b\u82f1\u56fd\u5b66\u8d39\u9700 CSC \u6216\u5956\u5b66\u91d1\u8986\u76d6\u3002\", \"sources\": [\"https://www.swansea.ac.uk/staff/l.evans\", \"https://www.swansea.ac.uk/culture-communication/postgraduate-research-profiles/zhennou-song\", \"https://cronfa.swan.ac.uk/Record/cronfa67352\", \"https://cronfa.swansea.ac.uk/Record/cronfa68918\", \"https://cronfa.swansea.ac.uk/Record/cronfa68918/Download/68918__33628__85f765f51a4d46f6b50e490c8981c76a.pdf\", \"https://www.swansea.ac.uk/staff/humanities-and-socialsciences/culture-communication-staff/media-communication-journalism-pr-staff/william.merrin\"], \"searched\": [\"Swansea \u5458\u5de5\u9875\uff08\u4e2d/\u82f1/\u5a01\u5c14\u58eb\u8bed\uff09\", \"Cronfa E-Theses\uff08\u6309 Supervisor \u68c0\u7d22\uff09\", \"Swansea \u7814\u7a76\u751f\u4e2a\u4eba\u9875\", \"\u5408\u4f5c\u5bfc\u5e08 William Merrin \u5458\u5de5\u9875 Supervision \u680f\", \"Web \u641c\u7d22\"]}, \"title_zh\": \"\u5a92\u4ecb\u7406\u8bba\u6559\u6388\uff1b\u5a92\u4ecb\u4e0e\u4f20\u64ad\u65b9\u5411\u8054\u5408\u8d1f\u8d23\u4eba\", \"unit_zh\": \"\u6587\u5316\u4e0e\u4f20\u64ad\u5b66\u9662\uff08\u5a92\u4f53\uff09\", \"evidence_projects_funding_zh\": \"\u4e3b\u9875\uff1a\u53ef\u6307\u5bfc\u7814\u7a76\u751f\uff08Available For Postgraduate Supervision\uff09\uff1b\u8457\u4f5c\u300a\u865a\u62df\u73b0\u5b9e\u7684\u518d\u5ea6\u5174\u8d77\u300b\uff08The Re-emergence of Virtual Reality\uff0c2018\uff09\u3001\u300a\u4ece\u5fae\u5b87\u5b99\u5230\u5143\u5b87\u5b99\u300b\uff08From Microverse to Metaverse\uff0c2022\uff09\u3001\u300a\u865a\u62df\u73b0\u5b9e\u6e38\u620f\u300b\uff08Virtual Reality Gaming\uff0c\u4e3b\u7f16\uff0c2025\uff09\uff1b2023 Dillwyn \u5956\u7ae0\uff1b2026 \u5f53\u9009\u5a01\u5c14\u58eb\u5b66\u4f1a\u4f1a\u58eb\uff08FLSW\uff09\uff1b\u66fe\u4efb CODAH \u6570\u5b57\u827a\u672f\u4e0e\u4eba\u6587\u4e2d\u5fc3\u4e3b\u4efb\uff1b\u6307\u5bfc Zhennuo Song\uff08VR \u535a\u7269\u9986\u4e2a\u6027\u5316\u4f53\u9a8c\uff09\u3001Evelyn Song\uff08VR/AR \u4e0e\u6587\u5316\u9057\u4ea7\uff09\u3002\", \"email_hook_zh\": \"\u60a8\u4e0e Evelyn Song \u5408\u8457\u7684\u6587\u7ae0\u300a\u6570\u5b57\u7269\u7684\u535a\u7269\u9986\u300b\uff08The museum of digital things\uff09\uff0c\u4ee5\u53ca\u60a8\u5173\u4e8e VR \u4e2d\u5177\u8eab\u4e0e\u4e34\u573a\u611f\u7684\u73b0\u8c61\u5b66\u7814\u7a76\uff0c\u662f\u6211\u627e\u5230\u7684\u4e0e\u6211\u624b\u52bf\u9a71\u52a8\u7684\u535a\u7269\u9986\u539f\u578b\u6700\u63a5\u8fd1\u7684\u5b66\u672f\u6846\u67b6\u3002\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Roberta Gilchrist\", \"school_en\": \"University of Reading\", \"school_zh\": \"\u96f7\u4e01\u5927\u5b66\", \"country\": \"\", \"title\": \"Professor of Archaeology; Research Dean \u2013 Heritage and Creativity\", \"unit\": \"Department of Archaeology\", \"homepage\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"email\": \"r.l.gilchrist@reading.ac.uk\", \"relevance\": 8, \"claim\": \"Gilchrist \u662f\u96f7\u4e01\u8003\u53e4\u5b66\u6559\u6388\u3001\u82f1\u56fd\u56fd\u5bb6\u5b66\u672f\u9662\u9662\u58eb\uff0c\u4e0e Arcade XR \u5408\u4f5c\u4e3a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\u5f00\u53d1 AR \u5e94\u7528\u5e76\u53d1\u8868'\u6c89\u6d78\u5f0f\u795e\u5723\u9057\u4ea7'\u8bba\u6587\uff0c\u662f\u96f7\u4e01\u4e0e\u7528\u6237'\u5b97\u6559\u9057\u4ea7\u6c89\u6d78\u4f53\u9a8c'\u6700\u5bf9\u53e3\u7684\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"evidence_papers\": [{\"title\": \"Immersive sacred heritage: enchantment through authenticity at Glastonbury Abbey\", \"year\": 2025, \"venue\": \"International Journal of Heritage Studies 31(7), pp.857-877\", \"url\": \"https://doi.org/10.1080/13527258.2025.2496888\", \"link_to_user\": \"\u795e\u5723\u9057\u4ea7\u7684\u6c89\u6d78\u8bbe\u8ba1\u4e0e\u771f\u5b9e\u6027 \u2192 \u6566\u714c\u4f5b\u50cf\u7948\u798f\u4f53\u9a8c\u7684\u4f26\u7406\u4e0e\u53d9\u4e8b\", \"title_zh\": \"\u6c89\u6d78\u5f0f\u5b97\u6559\u9057\u4ea7\uff1a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\u4e2d\u901a\u8fc7\u771f\u5b9e\u6027\u5b9e\u73b0\u7684\u9b45\u5316\"}, {\"title\": \"Sacred Heritage: Monastic Archaeology, Identities, Beliefs\", \"year\": 2020, \"venue\": \"Cambridge University Press (open access)\", \"url\": \"https://doi.org/10.1017/9781108678087\", \"link_to_user\": \"\u795e\u5723\u9057\u4ea7\u7684\u611f\u5b98\u4f53\u9a8c \u2192 '\u5c18-\u91d1-\u798f'\u4e09\u5e55\u4eea\u5f0f\u7684\u7406\u8bba\", \"title_zh\": \"\u795e\u5723\u9057\u4ea7\uff1a\u4fee\u9053\u9662\u8003\u53e4\u3001\u8eab\u4efd\u4e0e\u4fe1\u4ef0\"}], \"evidence_projects_funding\": \"\u4e3b\u9875\uff1a2022-3 \u4e0e Arcade\u3001Thread \u5171\u521b AR \u5e94\u7528 Glastonbury Stories \u53ca\u9057\u4ea7\u6b65\u9053\uff1b\u4e3a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\u5236\u5b9a\u65b0\u9610\u91ca\u7b56\u7565\uff082023\uff09\uff1bAHRC 'Glastonbury Abbey: Storytelling through Immersive Heritage Practice'\uff1bResearch Dean\uff08Heritage and Creativity\uff09\u3002\", \"fit_to_user\": \"'\u795e\u5723\u9057\u4ea7 + \u6c89\u6d78\u53d9\u4e8b + \u771f\u5b9e\u6027'\u4e0e\u7528\u6237\u6566\u714c\u4f5b\u50cf\u9879\u76ee\uff08\u62c2\u5c18\u3001\u4f9b\u706f\u7b49\u8654\u656c\u884c\u4e3a\u8f6c\u8bd1\u4e3a\u8eab\u4f53\u4ea4\u4e92\uff09\u5728\u6982\u5ff5\u4e0a\u9ad8\u5ea6\u4e00\u81f4\uff1b\u5979\u662f\u7814\u7a76\u9662\u957f\uff0c\u53ef\u8c03\u52a8\u8de8\u5b66\u79d1\u8d44\u6e90\u3002\", \"counterargument_risk\": \"\u8003\u53e4\u5b66\u80cc\u666f\uff0c\u4e0d\u505a\u4ea4\u4e92\u6280\u672f\u4e0e\u7167\u660e\uff1b\u7814\u7a76\u9662\u957f\u4e8b\u52a1\u7e41\u5fd9\uff1b\u96f7\u4e01 CSC \u53ea\u6709 5 \u4e2a\u540d\u989d\uff0c\u9700 2027-01-11 \u524d\u7533\u8bf7\u5165\u5b66\u3002\", \"email_hook\": \"Your article on immersive sacred heritage at Glastonbury Abbey addresses the question at the heart of my Dunhuang prototype: how to design immersion that respects the spiritual ethos of a sacred object.\", \"sources\": [\"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"https://centaur.reading.ac.uk/122797/\", \"https://orcid.org/0000-0002-1967-2558\"], \"verified\": true, \"csc_note\": \"\u96f7\u4e01\u2013CSC\uff1a\u4ec5 5 \u4e2a\u540d\u989d\uff0c\u9700\u5728 2027-01-11\uff08\u5468\u4e00\uff09\u524d\u63d0\u4ea4\u5165\u5b66\u7533\u8bf7\u3002\", \"matched_keywords\": [\"museum digital cultural heritage\", \"VR/AR/MR/XR\", \"narrative lighting\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"r.l.gilchrist@reading.ac.uk\", \"subject\": \"PhD enquiry (2027 entry): gesture-driven heritage interaction and narrative lighting\", \"body\": \"Dear Professor Gilchrist,\\n\\nYour article 'Immersive sacred heritage: enchantment through authenticity at Glastonbury Abbey' (2025) addresses the question at the heart of my Dunhuang prototype: how to design immersion that respects the spiritual ethos of sacred heritage. I would like to apply for a PhD at Reading under your supervision, through the University of Reading\u2013CSC scholarship.\\n\\nSince November 2025 I have directed the Digital Intangible Cultural Heritage Design and Production teaching and research office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting and leading a VR collaborative lighting design project (JAT251371). Before that I was a lighting hardware product manager: at OSRAM/LEDVANCE I ran nine product families (~100 SKUs, US$8M in sales) and worked on light-distribution analysis for Abu Dhabi's Zayed airport; at LEEDARSON I led user research for smart-lighting lines that sold over US$30M. Lighting work helps me design restrained, respectful light; my office consults heritage practitioners.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as Three.js GPU particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction that translates devotional acts (wiping dust, keeping lamps) into bodily gestures, combined with narrative lighting, can create authentic and respectful immersive encounters with sacred heritage. Your work on sacred heritage and authenticity would give this project its conceptual and ethical grounding, and I would welcome a technical co-supervisor through the Digital Humanities centre.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI understand that the Reading\u2013CSC route requires an admission application by 11 January 2027. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a\u683c\u62c9\u65af\u987f\u4f2f\u91cc'\u6c89\u6d78\u5f0f\u795e\u5723\u9057\u4ea7'\u8bba\u6587 \u2194 \u6566\u714c\u4f5b\u50cf\u8654\u656c\u884c\u4e3a\u7684\u624b\u52bf\u8f6c\u8bd1\uff0c\u6781\u5176\u8d34\u5408\u3002\u96f7\u4e01 CSC \u4ec5 5 \u4e2a\u540d\u989d\uff0c2027-01-11 \u524d\u7533\u8bf7\u5165\u5b66\u3002\u5efa\u8bae\u63d0\u8bae\u4e0e Guedes\uff08\u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\u8054\u5408\u4e3b\u4efb\uff09\u8054\u5408\u6307\u5bfc\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff082027 \u5e74\u5165\u5b66\uff09\uff1a\u624b\u52bf\u9a71\u52a8\u7684\u9057\u4ea7\u4ea4\u4e92\u4e0e\u53d9\u4e8b\u7167\u660e\", \"body_zh\": \"\u5c0a\u656c\u7684 Gilchrist \u6559\u6388\uff1a\\n\\n\u60a8\u7684\u6587\u7ae0'Immersive sacred heritage: enchantment through authenticity at Glastonbury Abbey'\uff08\u300a\u6c89\u6d78\u5f0f\u795e\u5723\u9057\u4ea7\uff1a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\u4e2d\u7ecf\u7531\u672c\u771f\u6027\u7684\u9b45\u5316\u300b\uff0c2025\uff09\u56de\u5e94\u4e86\u6211\u7684\u6566\u714c\u539f\u578b\u7684\u6838\u5fc3\u95ee\u9898\uff1a\u5982\u4f55\u8bbe\u8ba1\u5c0a\u91cd\u795e\u5723\u9057\u4ea7\u7cbe\u795e\u6c14\u8d28\u7684\u6c89\u6d78\u4f53\u9a8c\u3002\u6211\u5e0c\u671b\u901a\u8fc7\u96f7\u4e01\u5927\u5b66\u2013CSC \u5956\u5b66\u91d1\uff0c\u5728\u60a8\u7684\u6307\u5bfc\u4e0b\u7533\u8bf7\u96f7\u4e01\u5927\u5b66\u7684\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u9500\u552e\u989d 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed\uff08\u624e\u8036\u5fb7\uff09\u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u9500\u552e\u989d\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u7167\u660e\u5de5\u4f5c\u7ecf\u5386\u5e2e\u52a9\u6211\u8bbe\u8ba1\u514b\u5236\u800c\u606d\u656c\u7684\u5149\uff1b\u6211\u7684\u6559\u7814\u5ba4\u4f1a\u5411\u975e\u9057\u4ece\u4e1a\u8005\u5f81\u8be2\u610f\u89c1\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u77f3\u50cf\u663e\u73b0\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u91cd\u5efa\u4e3a Three.js GPU \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u57c3\u201d\u5e76\u53cc\u624b\u5408\u5341\uff0c\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u50cf\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u5bf9\u4e2d\u56fd\u9752\u94dc\u5668\u505a\u4e86\u540c\u6837\u7684\u5904\u7406\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\uff1a\u628a\u793c\u656c\u884c\u4e3a\uff08\u62c2\u5c18\u3001\u4f9b\u706f\uff09\u8f6c\u5316\u4e3a\u8eab\u4f53\u624b\u52bf\u7684\u624b\u52bf\u9a71\u52a8\u4ea4\u4e92\uff0c\u7ed3\u5408\u53d9\u4e8b\u7167\u660e\uff0c\u5982\u4f55\u4e0e\u795e\u5723\u9057\u4ea7\u5efa\u7acb\u672c\u771f\u800c\u606d\u656c\u7684\u6c89\u6d78\u5f0f\u76f8\u9047\u3002\u60a8\u5728\u795e\u5723\u9057\u4ea7\u4e0e\u672c\u771f\u6027\u65b9\u9762\u7684\u7814\u7a76\u5c06\u4e3a\u8fd9\u4e2a\u9879\u76ee\u63d0\u4f9b\u6982\u5ff5\u4e0e\u4f26\u7406\u57fa\u7840\uff0c\u6211\u4e5f\u6b22\u8fce\u901a\u8fc7\u6570\u5b57\u4eba\u6587\u4e2d\u5fc3\u5b89\u6392\u4e00\u4f4d\u6280\u672f\u65b9\u5411\u7684\u8054\u5408\u5bfc\u5e08\u3002\\n\\n\u5766\u7387\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u5408\u8457\u8fc7\u4e24\u7bc7 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5173\u4e8e MR \u5b9a\u5236\u65b9\u6cd5\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u636e\u6211\u4e86\u89e3\uff0c\u96f7\u4e01\u5927\u5b66\u2013CSC \u9014\u5f84\u8981\u6c42\u5728 2027 \u5e74 1 \u6708 11 \u65e5\u524d\u63d0\u4ea4\u5165\u5b66\u7533\u8bf7\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\\nHanlei (Eli) Zeng\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Lawrence Rees\", \"status\": \"current\", \"start_year\": 2021, \"thesis_title\": \"Reading Abbey: Connecting Archaeology, Heritage Management and Placemaking\", \"topic_zh\": \"\u96f7\u4e01\u4fee\u9053\u9662\uff1a\u8003\u53e4\u3001\u9057\u4ea7\u7ba1\u7406\u4e0e\u573a\u6240\u8425\u9020\uff08AHRC CDA\uff0c\u4e0e Reading Museum \u5408\u4f5c\uff0c\u542b\u6570\u5b57\u53ef\u89c6\u5316/\u6c89\u79ef\u5efa\u6a21\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/lawrence-rees\", \"background\": \"UCL \u8003\u53e4\u5b66\u58eb\uff0c\u5251\u6865\u8003\u53e4\u961f\u7530\u91ce\u8003\u53e4\u5e08\", \"chinese_or_csc\": false}, {\"name\": \"Jillian Reid\", \"status\": \"current\", \"research_topic\": \"late medieval women's lives through archaeological material in national museum collections (British Museum, NMS, NMW)\", \"topic_zh\": \"\u901a\u8fc7\u56fd\u5bb6\u535a\u7269\u9986\u85cf\u54c1\u7814\u7a76\u4e2d\u4e16\u7eaa\u665a\u671f\u5973\u6027\u751f\u6d3b\uff08SWW DTP \u8d44\u52a9\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/jillian-reid\", \"chinese_or_csc\": false}, {\"name\": \"King\", \"status\": \"alumni\", \"research_topic\": \"medieval and early modern households in Norwich\", \"topic_zh\": \"\u8bfa\u91cc\u5947\u4e2d\u4e16\u7eaa\u4e0e\u8fd1\u4ee3\u65e9\u671f\u5bb6\u6237\uff08\u5e74\u4efd\u672a\u6ce8\u660e\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"chinese_or_csc\": false}, {\"name\": \"Foyle\", \"status\": \"alumni\", \"research_topic\": \"Hampton Court Palace\", \"topic_zh\": \"\u6c49\u666e\u987f\u5bab\u8003\u53e4\uff08\u5e74\u4efd\u672a\u6ce8\u660e\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"chinese_or_csc\": false}, {\"name\": \"Bishop (now Green)\", \"status\": \"alumni\", \"research_topic\": \"the medieval Quarr stone industry\", \"topic_zh\": \"\u4e2d\u4e16\u7eaa Quarr \u77f3\u6750\u4ea7\u4e1a\uff08\u5e74\u4efd\u672a\u6ce8\u660e\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"chinese_or_csc\": false}, {\"name\": \"Nimmo\", \"status\": \"alumni\", \"research_topic\": \"gender and ethnicity in the convents of early modern Ecuador\", \"topic_zh\": \"\u8fd1\u4ee3\u65e9\u671f\u5384\u74dc\u591a\u5c14\u4fee\u9053\u9662\u7684\u6027\u522b\u4e0e\u65cf\u7fa4\uff08\u5e74\u4efd\u672a\u6ce8\u660e\uff09\", \"url\": \"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"chinese_or_csc\": false}], \"total_estimate\": \"\u5df2\u5b8c\u6210 13 \u540d\u535a\u58eb\uff082021 \u5e74 CDA \u7533\u8bf7\u4e66\u6240\u8ff0\uff09\uff1b\u5728\u8bfb\u81f3\u5c11 2\", \"student_pattern_zh\": \"\u4e2d\u4e16\u7eaa\u793e\u4f1a\u8003\u53e4\uff1a\u4fee\u9053\u9662\u3001\u6027\u522b\u3001\u5893\u846c\u3001\u5bb6\u6237\u3001\u5efa\u7b51\u4e0e\u666f\u89c2\uff1b\u8fd1\u5e74\u4e0e\u535a\u7269\u9986/\u9057\u4ea7\u673a\u6784\u5408\u4f5c(CDA)\u5e76\u5f15\u5165\u6570\u5b57\u53ef\u89c6\u5316\u3002\u5b98\u7f51\u540d\u5355\u4e3a\u59d3\u6c0f+\u8bfe\u9898\uff0c\u5e74\u4efd\u591a\u672a\u6ce8\u660e\uff0c\u90e8\u5206\u53ef\u80fd\u65e9\u4e8e\u8fd1 10 \u5e74\u3002\", \"design_background_ok_zh\": \"\u5b66\u751f\u5747\u4e3a\u8003\u53e4/\u5386\u53f2\u80cc\u666f\uff1b\u672a\u89c1\u8bbe\u8ba1\u80cc\u666f\u3002\", \"chinese_students_zh\": \"\u672a\u67e5\u5230\u3002\", \"implication_zh\": \"\u9ad8\u5ea6\u4eba\u6587\u8003\u53e4\u5bfc\u5411\uff0c\u4e0e\u8bbe\u8ba1\u5b9e\u8df5\u8ddd\u79bb\u8f83\u5927\uff1b\u53ef\u4ece\u5176'\u795e\u5723\u9057\u4ea7\u7684\u611f\u5b98\u4f53\u9a8c'\uff08Glastonbury \u4fee\u9053\u9662\u9610\u91ca\u3001MeRit \u4e0e\u5927\u82f1\u535a\u7269\u9986\u6570\u5b57\u4eba\u6587\u9879\u76ee\uff09\u5207\u5165'\u5b97\u6559/\u4eea\u5f0f\u9057\u4ea7\u7684\u5149\u4e0e\u611f\u5b98\u53d9\u4e8b'\u3002\u98ce\u9669\uff1a\u9700\u8003\u53e4\u5b66\u8bad\u7ec3\uff0c\u4f5c\u4e3a\u4e3b\u5bfc\u4e0d\u592a\u73b0\u5b9e\uff0c\u9002\u5408\u4f5c\u4eba\u6587\u526f\u5bfc\u3002\", \"sources\": [\"https://www.reading.ac.uk/archaeology/staff/roberta-gilchrist-fba\", \"https://www.reading.ac.uk/archaeology/staff/lawrence-rees\", \"https://www.reading.ac.uk/archaeology/staff/jillian-reid\", \"https://docslib.org/doc/414151/connecting-archaeology-heritage-management-and-placemaking\"], \"searched\": [\"Reading \u8003\u53e4\u7cfb\u6559\u5e08\u9875\u4e0e PGR \u5b66\u751f\u9875\", \"CDA \u9879\u76ee\u7533\u8bf7\u6587\u672c\", \"CentAUR \u672a\u5355\u72ec\u68c0\u7d22\u5bfc\u5e08\u5b57\u6bb5\"]}, \"title_zh\": \"\u8003\u53e4\u5b66\u6559\u6388\uff1b\u7814\u7a76\u9662\u957f\u2014\u2014\u9057\u4ea7\u4e0e\u521b\u610f\", \"unit_zh\": \"\u8003\u53e4\u5b66\u7cfb\", \"evidence_projects_funding_zh\": \"\u4e3b\u9875\uff1a2022-3 \u4e0e Arcade\u3001Thread \u5171\u521b AR \u5e94\u7528\u300a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u6545\u4e8b\u300b\uff08Glastonbury Stories\uff09\u53ca\u9057\u4ea7\u6b65\u9053\uff1b\u4e3a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\u5236\u5b9a\u65b0\u9610\u91ca\u7b56\u7565\uff082023\uff09\uff1bAHRC \u9879\u76ee\u300a\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\uff1a\u901a\u8fc7\u6c89\u6d78\u5f0f\u9057\u4ea7\u5b9e\u8df5\u8bb2\u6545\u4e8b\u300b\uff08Glastonbury Abbey: Storytelling through Immersive Heritage Practice\uff09\uff1b\u7814\u7a76\u9662\u957f\uff08\u9057\u4ea7\u4e0e\u521b\u610f\u65b9\u5411\uff09\u3002\", \"email_hook_zh\": \"\u60a8\u5173\u4e8e\u683c\u62c9\u65af\u987f\u4f2f\u91cc\u4fee\u9053\u9662\uff08Glastonbury Abbey\uff09\u6c89\u6d78\u5f0f\u795e\u5723\u9057\u4ea7\u7684\u6587\u7ae0\uff0c\u56de\u5e94\u4e86\u6211\u6566\u714c\u539f\u578b\u7684\u6838\u5fc3\u95ee\u9898\uff1a\u5982\u4f55\u8bbe\u8ba1\u5c0a\u91cd\u795e\u5723\u5bf9\u8c61\u7cbe\u795e\u6c14\u8d28\u7684\u6c89\u6d78\u4f53\u9a8c\u3002\", \"csc_status_zh\": \"\u6d3b\u8dc3\"}, {\"name\": \"Jenny Kidd\", \"school_en\": \"Cardiff University\", \"school_zh\": \"\u5361\u8fea\u592b\u5927\u5b66\", \"country\": \"\", \"title\": \"Reader in Digital Culture; Director of Research (Development and Environment)\", \"unit\": \"School of Journalism, Media and Culture (JOMEC)\", \"homepage\": \"https://profiles.cardiff.ac.uk/staff/kiddjc2\", \"email\": \"KiddJC2@cardiff.ac.uk\", \"relevance\": 8, \"claim\": \"Kidd \u662f\u5361\u8fea\u592b\u505a'\u6c89\u6d78\u5f0f\u9057\u4ea7\u4f53\u9a8c/\u535a\u7269\u9986\u6570\u5b57\u53d9\u4e8b'\u6700\u6709\u4ee3\u8868\u6027\u7684\u5b66\u8005\uff08With New Eyes I See \u7528\u624b\u7535+\u6295\u5f71\u89e6\u53d1\u9057\u5740\u53d9\u4e8b\uff09\uff0c\u5b98\u65b9\u9875\u6807\u660e\u53ef\u6307\u5bfc\u7814\u7a76\u751f\uff0c\u662f\u5361\u8fea\u592b\u4e0e\u7528\u6237'\u53d9\u4e8b\u7167\u660e+\u9057\u4ea7'\u6700\u5bf9\u53e3\u7684\u5bfc\u5e08\u3002\", \"evidence_homepage\": \"https://profiles.cardiff.ac.uk/staff/kiddjc2\", \"evidence_papers\": [{\"title\": \"With new eyes I see: embodiment, empathy and silence in digital heritage interpretation\", \"year\": 2019, \"venue\": \"International Journal of Heritage Studies 25(1)\", \"url\": \"https://doi.org/10.1080/13527258.2017.1341946\", \"link_to_user\": \"\u7528\u624b\u7535/\u6295\u5f71/RFID \u89e6\u53d1\u7684\u9057\u5740\u7eaa\u5f55\u7247 \u2192 '\u5149\u4f5c\u4e3a\u53d9\u4e8b\u89e6\u53d1\u5668'\u7684\u76f4\u63a5\u5148\u4f8b\", \"title_zh\": \"\u4ee5\u65b0\u7684\u773c\u775b\u89c2\u770b\uff1a\u6570\u5b57\u9057\u4ea7\u9610\u91ca\u4e2d\u7684\u5177\u8eab\u3001\u5171\u60c5\u4e0e\u6c89\u9ed8\"}, {\"title\": \"Evaluating digital cultural heritage 'in the wild': The case for reflexivity\", \"year\": 2019, \"venue\": \"Journal on Computing and Cultural Heritage 12(1)\", \"url\": \"https://doi.org/10.1145/3287272\", \"link_to_user\": \"\u771f\u5b9e\u573a\u666f\u8bc4\u4f30\u65b9\u6cd5 \u2192 RQ3 \u73b0\u573a\u90e8\u7f72\u7684\u8bc4\u4f30\u8bbe\u8ba1\", \"title_zh\": \"\u201c\u5728\u771f\u5b9e\u573a\u666f\u4e2d\u201d\u8bc4\u4f30\u6570\u5b57\u6587\u5316\u9057\u4ea7\uff1a\u53cd\u8eab\u6027\u7684\u5fc5\u8981\u6027\"}, {\"title\": \"Evaluating the affective dimensions of Traces-Olion: a subtle mob at St Fagans National Museum of History, Wales\", \"year\": 2018, \"venue\": \"DigitalHERITAGE 2018 (IEEE)\", \"url\": \"https://doi.org/10.1109/DigitalHeritage.2018.8810117\", \"link_to_user\": \"\u535a\u7269\u9986\u6c89\u6d78\u4f53\u9a8c\u60c5\u611f\u8bc4\u4f30 \u2192 \u60c5\u611f\u6295\u5165\u6d4b\u91cf\", \"title_zh\": \"\u8bc4\u4f30 Traces-Olion \u7684\u60c5\u611f\u7ef4\u5ea6\uff1a\u5728\u5a01\u5c14\u58eb\u5723\u6cd5\u6839\u56fd\u5bb6\u5386\u53f2\u535a\u7269\u9986\u7684\u4e00\u6b21\u5fae\u5999\u5feb\u95ea\"}], \"evidence_projects_funding\": \"\u4e3b\u9875\uff1aLeverhulme Synthetic Pasts\uff082024-26\uff0cPI\uff09\uff1bAHRC Policy and Evidence Centre Co-I\uff1bAHRC-REACT 'With New Eyes I See'\uff1bESRC IAA Traces|Olion\uff08St Fagans \u56fd\u5bb6\u5386\u53f2\u535a\u7269\u9986\uff09\uff1bImmersive Media for Change\uff1b\u8457\u4f5c Critical Encounters with Immersive Storytelling (2019)\u3001Museums in the New Mediascape (2014)\uff1bTuring Fellow 2024-26\uff1b\u6307\u5bfc\u65b9\u5411\uff1adigital heritage, digital memory, synthetic media\u3002\", \"fit_to_user\": \"'\u5177\u8eab\u3001\u5171\u60c5\u3001\u6c89\u9ed8'\u4e0e Stone Reveal \u7684\u62c2\u5c18\u4eea\u5f0f\u9ad8\u5ea6\u5951\u5408\uff1b\u5979\u505a\u8fc7\u7528\u5149\u6e90\u89e6\u53d1\u53d9\u4e8b\u7684\u9057\u5740\u4f5c\u54c1\uff0c\u53ef\u76f4\u63a5\u652f\u6491'\u53d9\u4e8b\u7167\u660e'\u6982\u5ff5\uff1b\u6df7\u5408\u65b9\u6cd5+\u521b\u610f\u65b9\u6cd5\u4e0e\u7528\u6237 RtD \u4e00\u81f4\u3002\", \"counterargument_risk\": \"\u5b66\u9662\u4e3a\u65b0\u95fb/\u5a92\u4f53/\u6587\u5316\uff0c\u504f\u6279\u5224\u4e0e\u8d28\u6027\u7814\u7a76\uff0c\u4e0d\u505a\u6280\u672f\u5f00\u53d1\u4e0e\u5bf9\u7167\u5b9e\u9a8c\uff1b\u8fd1\u5e74\u91cd\u5fc3\u8f6c\u5411 AI/\u5408\u6210\u8bb0\u5fc6\uff1b\u5361\u8fea\u592b CSC \u9700 2026-11-03 \u524d\u5b8c\u6210\u5165\u5b66\u7533\u8bf7\uff0c\u65f6\u95f4\u6781\u7d27\u3002\", \"email_hook\": \"Your project 'With New Eyes I See', where torchlight and projection triggered heritage storytelling on site, is the closest precedent I know for using light itself as a narrative interface.\", \"sources\": [\"https://profiles.cardiff.ac.uk/staff/kiddjc2\", \"https://orcid.org/0000-0003-0188-2140\", \"https://doi.org/10.1080/13527258.2017.1341946\"], \"verified\": true, \"csc_note\": \"\u5361\u8fea\u592b\u2013CSC\uff1a\u6700\u591a 40 \u540d\uff08\u5dee\u989d\uff0c\u5b66\u6821\u4ec5\u514d\u5b66\u8d39\uff09\uff0c\u9700\u5728 2026-11-03 \u524d\u5411\u5361\u8fea\u592b\u63d0\u4ea4\u5165\u5b66\u7533\u8bf7\u3002\", \"matched_keywords\": [\"narrative lighting\", \"museum digital cultural heritage\", \"gesture/embodied interaction\", \"digital media\"], \"csc_status\": \"active\", \"in_user_csc_list\": true, \"email_draft\": {\"to\": \"KiddJC2@cardiff.ac.uk\", \"subject\": \"PhD enquiry (2027 entry): gesture-driven heritage interaction and narrative lighting\", \"body\": \"Dear Dr Kidd,\\n\\nYour project 'With New Eyes I See', in which torchlight, projection and RFID triggered a site-specific documentary, and your article on embodiment, empathy and silence in digital heritage interpretation are the closest precedent I know for using light itself as a narrative interface. I would like to apply for a PhD at JOMEC, Cardiff University under your supervision, through the Cardiff University\u2013CSC scholarship.\\n\\nSince November 2025 I have directed the Digital Intangible Cultural Heritage Design and Production teaching and research office at Quanzhou Huaguang College, teaching 3D character design and digital sculpting and leading a VR collaborative lighting design project (JAT251371). Before that I was a lighting hardware product manager: at OSRAM/LEDVANCE I ran nine product families (~100 SKUs, US$8M in sales) and worked on light-distribution analysis for Abu Dhabi's Zayed airport; at LEEDARSON I led user research for smart-lighting lines that sold over US$30M. Product work makes light-as-interface robust; my office provides partners for evaluation in the wild.\\n\\nMy most relevant prototype is Stone Reveal (https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/): four Dunhuang Buddha figures rebuilt as Three.js GPU particle clouds; with in-browser MediaPipe hand tracking, visitors brush away the \\\"dust\\\" and join palms to reveal the gilded figure. A companion project does the same for Chinese bronzes.\\n\\nFor a PhD I would like to study how gesture-driven interaction and responsive, narrative lighting shape embodiment, empathy and cultural learning in museum heritage experiences, combining practice-based prototypes with reflexive evaluation in the wild. Your work on immersive heritage encounters and on evaluating digital heritage in the wild would give this project its conceptual and methodological frame.\\n\\nTo be direct: my degrees are in design, not computer science, and I have no first-author paper yet (I co-authored two MR papers). I bring working prototypes, a granted invention patent on an MR customisation method, and a practice-based approach I would turn into peer-reviewed studies early.\\n\\nI understand that Cardiff's CSC route requires a PhD application by 3 November 2026, so I am writing early. Would you be open to supervising this topic? I would be glad to send a two-page proposal.\\n\\nBest regards,\\nHanlei (Eli) Zeng\\nDirector, Digital ICH Design & Production Teaching and Research Office, Quanzhou Huaguang College, China\\nPortfolio & CV: https://cooleli.github.io/CV-project/v2/\", \"note_zh\": \"\u5207\u5165\u70b9\uff1a'With New Eyes I See'\uff08\u624b\u7535/\u6295\u5f71\u89e6\u53d1\u53d9\u4e8b\uff09= \u53d9\u4e8b\u7167\u660e\u5148\u4f8b\u3002\u6ce8\u610f\uff1a\u5361\u8fea\u592b CSC \u8981\u6c42 2026-11-03 \u524d\u63d0\u4ea4\u5165\u5b66\u7533\u8bf7\u2014\u2014\u5fc5\u987b\u672c\u5468\u5185\u53d1\u4fe1\u3002\u53d1\u9001\u524d\u786e\u8ba4\uff1aJOMEC \u662f\u5426\u63a5\u53d7\u5b9e\u8df5\u578b\u535a\u58eb\uff1b\u82f1\u8bed\u6210\u7ee9\u65f6\u95f4\u3002\", \"subject_zh\": \"\u535a\u58eb\u7533\u8bf7\u54a8\u8be2\uff082027 \u5e74\u5165\u5b66\uff09\uff1a\u624b\u52bf\u9a71\u52a8\u7684\u9057\u4ea7\u4ea4\u4e92\u4e0e\u53d9\u4e8b\u7167\u660e\", \"body_zh\": \"\u5c0a\u656c\u7684 Kidd \u535a\u58eb\uff1a\\n\\n\u60a8\u7684\u9879\u76ee'With New Eyes I See'\uff08\u300a\u4ee5\u65b0\u7684\u773c\u775b\u6211\u770b\u89c1\u300b\uff09\u7528\u624b\u7535\u5149\u3001\u6295\u5f71\u548c RFID \u89e6\u53d1\u4e00\u90e8\u7279\u5b9a\u573a\u5730\u7eaa\u5f55\u7247\uff0c\u4ee5\u53ca\u60a8\u5173\u4e8e\u6570\u5b57\u9057\u4ea7\u9610\u91ca\u4e2d\u7684\u5177\u8eab\u3001\u5171\u60c5\u4e0e\u6c89\u9ed8\u7684\u6587\u7ae0\uff0c\u662f\u6211\u6240\u77e5\u9053\u7684\u628a\u5149\u672c\u8eab\u7528\u4f5c\u53d9\u4e8b\u754c\u9762\u7684\u6700\u63a5\u8fd1\u7684\u5148\u4f8b\u3002\u6211\u5e0c\u671b\u901a\u8fc7\u5361\u8fea\u592b\u5927\u5b66\u2013CSC \u5956\u5b66\u91d1\uff0c\u5728\u60a8\u7684\u6307\u5bfc\u4e0b\u7533\u8bf7\u5361\u8fea\u592b\u5927\u5b66\u65b0\u95fb\u3001\u5a92\u4f53\u4e0e\u6587\u5316\u5b66\u9662\uff08JOMEC\uff09\u7684\u535a\u58eb\u3002\\n\\n\u81ea 2025 \u5e74 11 \u6708\u8d77\uff0c\u6211\u62c5\u4efb\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662\u6570\u5b57\u975e\u7269\u8d28\u6587\u5316\u9057\u4ea7\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\uff0c\u4e3b\u8bb2 3D \u89d2\u8272\u8bbe\u8ba1\u4e0e\u6570\u5b57\u96d5\u523b\uff0c\u5e76\u4e3b\u6301\u4e00\u9879 VR \u534f\u540c\u7167\u660e\u8bbe\u8ba1\u7814\u7a76\u9879\u76ee\uff08JAT251371\uff09\u3002\u6b64\u524d\u6211\u662f\u7167\u660e\u786c\u4ef6\u4ea7\u54c1\u7ecf\u7406\uff1a\u5728 OSRAM/LEDVANCE\uff08\u6b27\u53f8\u6717/\u6717\u5fb7\u4e07\u65af\uff09\u8d1f\u8d23 9 \u4e2a\u4ea7\u54c1\u7cfb\u5217\uff08\u7ea6 100 \u4e2a SKU\uff0c\u9500\u552e\u989d 800 \u4e07\u7f8e\u5143\uff09\uff0c\u5e76\u53c2\u4e0e\u963f\u5e03\u624e\u6bd4 Zayed\uff08\u624e\u8036\u5fb7\uff09\u673a\u573a\u9879\u76ee\u7684\u914d\u5149\u5206\u6790\uff1b\u5728 LEEDARSON\uff08\u7acb\u8fbe\u4fe1\uff09\u4e3b\u5bfc\u667a\u80fd\u7167\u660e\u4ea7\u54c1\u7ebf\u7684\u7528\u6237\u7814\u7a76\uff0c\u76f8\u5173\u4ea7\u54c1\u9500\u552e\u989d\u8d85\u8fc7 3000 \u4e07\u7f8e\u5143\u3002\u4ea7\u54c1\u5de5\u4f5c\u8ba9\u201c\u4ee5\u5149\u4e3a\u754c\u9762\u201d\u66f4\u52a0\u7a33\u5065\uff1b\u6211\u7684\u6559\u7814\u5ba4\u80fd\u4e3a\u771f\u5b9e\u573a\u666f\u8bc4\u4f30\u63d0\u4f9b\u5408\u4f5c\u4f19\u4f34\u3002\\n\\n\u4e0e\u6b64\u6700\u76f8\u5173\u7684\u539f\u578b\u662f Stone Reveal\uff08\u77f3\u50cf\u663e\u73b0\uff09\uff08https://cooleli.github.io/Portfolio-page/Dunhuang%20Interactive%20Heritage%20project/\uff09\uff1a\u56db\u5c0a\u6566\u714c\u4f5b\u50cf\u88ab\u91cd\u5efa\u4e3a Three.js GPU \u7c92\u5b50\u4e91\uff1b\u501f\u52a9\u6d4f\u89c8\u5668\u5185\u7684 MediaPipe \u624b\u90e8\u8ffd\u8e2a\uff0c\u89c2\u4f17\u62c2\u53bb\u201c\u5c18\u57c3\u201d\u5e76\u53cc\u624b\u5408\u5341\uff0c\u5373\u53ef\u663e\u73b0\u938f\u91d1\u4f5b\u50cf\u3002\u53e6\u4e00\u4e2a\u914d\u5957\u9879\u76ee\u5bf9\u4e2d\u56fd\u9752\u94dc\u5668\u505a\u4e86\u540c\u6837\u7684\u5904\u7406\u3002\\n\\n\u5728\u535a\u58eb\u9636\u6bb5\uff0c\u6211\u5e0c\u671b\u7814\u7a76\u624b\u52bf\u9a71\u52a8\u7684\u4ea4\u4e92\u4e0e\u54cd\u5e94\u5f0f\u53d9\u4e8b\u7167\u660e\u5982\u4f55\u5851\u9020\u535a\u7269\u9986\u9057\u4ea7\u4f53\u9a8c\u4e2d\u7684\u5177\u8eab\u6027\u3001\u5171\u60c5\u548c\u6587\u5316\u5b66\u4e60\uff0c\u628a\u5b9e\u8df5\u578b\u539f\u578b\u4e0e\u5728\u771f\u5b9e\u573a\u666f\u4e2d\u7684\u53cd\u601d\u6027\u8bc4\u4f30\u76f8\u7ed3\u5408\u3002\u60a8\u5173\u4e8e\u6c89\u6d78\u5f0f\u9057\u4ea7\u76f8\u9047\u4ee5\u53ca\u5728\u771f\u5b9e\u573a\u666f\u4e2d\u8bc4\u4f30\u6570\u5b57\u9057\u4ea7\u7684\u7814\u7a76\uff0c\u5c06\u4e3a\u8fd9\u4e2a\u9879\u76ee\u63d0\u4f9b\u6982\u5ff5\u548c\u65b9\u6cd5\u6846\u67b6\u3002\\n\\n\u5766\u7387\u5730\u8bf4\uff1a\u6211\u7684\u5b66\u4f4d\u90fd\u662f\u8bbe\u8ba1\u4e13\u4e1a\u800c\u975e\u8ba1\u7b97\u673a\u79d1\u5b66\uff0c\u76ee\u524d\u8fd8\u6ca1\u6709\u7b2c\u4e00\u4f5c\u8005\u8bba\u6587\uff08\u6211\u5408\u8457\u8fc7\u4e24\u7bc7 MR \u8bba\u6587\uff09\u3002\u6211\u80fd\u5e26\u6765\u53ef\u8fd0\u884c\u7684\u539f\u578b\u3001\u4e00\u9879\u5173\u4e8e MR \u5b9a\u5236\u65b9\u6cd5\u7684\u5df2\u6388\u6743\u53d1\u660e\u4e13\u5229\uff0c\u4ee5\u53ca\u4e00\u79cd\u5b9e\u8df5\u578b\u7814\u7a76\u65b9\u6cd5\u2014\u2014\u6211\u4f1a\u5c3d\u65e9\u5c06\u5176\u8f6c\u5316\u4e3a\u7ecf\u540c\u884c\u8bc4\u5ba1\u7684\u7814\u7a76\u6210\u679c\u3002\\n\\n\u636e\u6211\u4e86\u89e3\uff0c\u5361\u8fea\u592b\u5927\u5b66\u7684 CSC \u9014\u5f84\u8981\u6c42\u5728 2026 \u5e74 11 \u6708 3 \u65e5\u524d\u63d0\u4ea4\u535a\u58eb\u7533\u8bf7\uff0c\u6240\u4ee5\u6211\u63d0\u65e9\u5199\u4fe1\u3002\u8bf7\u95ee\u60a8\u662f\u5426\u613f\u610f\u6307\u5bfc\u8fd9\u4e00\u8bfe\u9898\uff1f\u6211\u5f88\u4e50\u610f\u53d1\u9001\u4e00\u4efd\u4e24\u9875\u7684\u7814\u7a76\u8ba1\u5212\u3002\\n\\n\u6b64\u81f4\u656c\u793c\\nHanlei (Eli) Zeng\\n\u4e2d\u56fd\u6cc9\u5dde\u534e\u5149\u804c\u4e1a\u5b66\u9662 \u6570\u5b57\u975e\u9057\u8bbe\u8ba1\u4e0e\u5236\u4f5c\u6559\u7814\u5ba4\u4e3b\u4efb\\n\u4f5c\u54c1\u96c6\u4e0e\u7b80\u5386\uff1ahttps://cooleli.github.io/CV-project/v2/\"}, \"phd_students\": {\"found\": true, \"students\": [{\"name\": \"Salsabilla Sakinah\", \"status\": \"current\", \"research_topic\": \"Activist museography and immersive practice in the climate emergency\", \"topic_zh\": \"\u6c14\u5019\u5371\u673a\u4e2d\u7684\u884c\u52a8\u4e3b\u4e49\u535a\u7269\u9986\u5c55\u9648\u4e0e\u6c89\u6d78\u5f0f\u5b9e\u8df5\uff08\u4e0e Kidd \u5408\u8457\u7ae0\u8282\uff09\", \"url\": \"https://profiles.cardiff.ac.uk/staff/sakinahs\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Kirstin Mitchell\", \"status\": \"current\", \"research_topic\": null, \"topic_zh\": \"\uff08\u8bfe\u9898\u672a\u516c\u5f00\uff09\", \"url\": \"https://profiles.cardiff.ac.uk/staff/mitchellk8\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Aled Pickard\", \"status\": \"current\", \"research_topic\": null, \"topic_zh\": \"\uff08\u8bfe\u9898\u672a\u516c\u5f00\uff09\", \"url\": \"https://profiles.cardiff.ac.uk/research-staff/pickarda\", \"now\": null, \"background\": null, \"chinese_or_csc\": null}, {\"name\": \"Nan Hu\", \"status\": \"alumni\", \"graduation_year\": 2022, \"thesis_title\": \"Exploring the Transformation of Museums into Cultural Hubs\", \"topic_zh\": \"\u535a\u7269\u9986\u5411\u6587\u5316\u67a2\u7ebd\u7684\u8f6c\u578b\uff08\u6848\u4f8b\uff1a\u6df1\u5733\u8bbe\u8ba1\u4e92\u8054 Design Society \u7684\u89c2\u4f17\u4f53\u9a8c\uff09\", \"url\": \"https://orca.cardiff.ac.uk/id/eprint/151870/1/2022hunphd.pdf\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u4e0e Kidd \u5408\u8457 Curator 2024 \u8bba\u6587\uff1bKidd \u4e3a\u5bfc\u5e08\u7cfb\u63a8\u65ad\uff08\u8bba\u6587\u81f4\u8c22\u672a\u80fd\u4e0b\u8f7d\u6838\u5b9e\uff09\"}, {\"name\": \"G. N. R. A. Anderson\", \"status\": \"alumni\", \"graduation_year\": 2023, \"thesis_title\": \"Exploring the Practices for Sustainable Site-Specific ...\uff08\u9898\u76ee\u622a\u65ad\uff0c\u89c1 ORCA\uff09\", \"topic_zh\": \"\u53ef\u6301\u7eed\u7684\u573a\u57df\u7279\u5b9a\uff08site-specific\uff09\u8868\u6f14/\u521b\u4f5c\u5b9e\u8df5\", \"url\": \"https://orca.cardiff.ac.uk/id/eprint/158422/1/2023andersongnraphd.pdf\", \"now\": null, \"background\": \"\u6f14\u5458/\u8868\u6f14\u8bad\u7ec3\u80cc\u666f\uff08\u81f4\u8c22\u81ea\u8ff0\uff09\", \"chinese_or_csc\": null, \"note\": \"\u81f4\u8c22\u79f0 'my supervisor Dr Jenny Kidd'\", \"note_zh\": \"\u81f4\u8c22\u79f0\u201cmy supervisor Dr Jenny Kidd\u201d\uff08\u6211\u7684\u5bfc\u5e08 Jenny Kidd \u535a\u58eb\uff09\"}, {\"name\": \"C. A. Westwater\", \"status\": \"alumni\", \"graduation_year\": 2021, \"thesis_title\": \"How power performs in co-curatorial participation, 2013-2020\", \"topic_zh\": \"\u5171\u540c\u7b56\u5c55\u53c2\u4e0e\u4e2d\u7684\u6743\u529b\u8fd0\u4f5c\", \"url\": \"https://orca.cardiff.ac.uk/id/eprint/140868/1/2021westwatercaphd.pdf\", \"now\": null, \"background\": null, \"chinese_or_csc\": null, \"note\": \"\u5bfc\u5e08 Jenny Kidd \u4e0e Kerry Moore\uff1bPresident's Scholarship\", \"note_zh\": \"\u5bfc\u5e08 Jenny Kidd \u4e0e Kerry Moore\uff1b\u6821\u957f\u5956\u5b66\u91d1\uff08President's Scholarship\uff09\"}, {\"name\": \"A. Payson\", \"status\": \"alumni\", \"graduation_year\": 2018, \"thesis_title\": \"Feeling together: Emotion, heritage, conviviality and politics in a changing city\", \"topic_zh\": \"\u53d8\u8fc1\u57ce\u5e02\u4e2d\u7684\u60c5\u611f\u3001\u9057\u4ea7\u4e0e\u5171\u5904\u653f\u6cbb\", \"url\": \"https://orca.cardiff.ac.uk/id/eprint/108561/12/2018PaysonA%20108561%20DPR.pdf\", \"now\": null, \"background\"");